DATA = "diff --git a/src/browser/chatgptFiles.ts b/src/browser/chatgptFiles.ts\nnew file mode 100644\nindex 0000000..cc05385\n--- /dev/null\n+++ b/src/browser/chatgptFiles.ts\n@@ -0,0 +1,100 @@\n+import fs from \"node:fs/promises\";\n+import path from \"node:path\";\n+import type { SessionArtifact } from \"../sessionStore.js\";\n+import type { BrowserLogger, ChromeClient } from \"./types.js\";\n+import { resolveSessionArtifactsDir } from \"./artifacts.js\";\n+\n+const MAX_FILES = 20;\n+const MAX_BYTES = 100 * 1024 * 1024;\n+const DOWNLOAD_TIMEOUT_MS = 30_000;\n+const SANDBOX_PREFIX = \"sandbox:/mnt/data/\";\n+const DOWNLOAD_BASE = \"https://chatgpt.com/backend-api/files/sandbox/mnt/data/\";\n+\n+export function extractChatGptSandboxFiles(markdown: string): string[] {\n+  const matches = markdown.matchAll(/sandbox:\\/mnt\\/data\\/[^\\s<>\"')\\]]+/g);\n+  const unique = new Set<string>();\n+  for (const match of matches) {\n+    const candidate = match[0].replace(/[.,;!?]+$/, \"\");\n+    const relative = candidate.slice(SANDBOX_PREFIX.length);\n+    if (relative.length > 1024 || !relative || /[%?#\\\\\\x00-\\x1f]/.test(relative)) continue;\n+    const parts = relative.split(\"/\");\n+    if (parts.some((part) => !part || part === \".\" || part === \"..\" || !/^[\\w. -]+$/.test(part))) continue;\n+    unique.add(candidate);\n+    if (unique.size >= MAX_FILES) break;\n+  }\n+  return [...unique];\n+}\n+\n+async function reserveFile(dir: string, filename: string) {\n+  const ext = path.extname(filename);\n+  const stem = filename.slice(0, filename.length - ext.length);\n+  for (let attempt = 0; attempt < 1000; attempt += 1) {\n+    const candidate = path.join(dir, attempt ? `${stem}-${attempt + 1}${ext}` : filename);\n+    try {\n+      return { file: await fs.open(candidate, \"wx\", 0o600), target: candidate };\n+    } catch (error) {\n+      if ((error as NodeJS.ErrnoException).code !== \"EEXIST\") throw error;\n+    }\n+  }\n+  throw new Error(\"Could not allocate unique artifact filename\");\n+}\n+\n+export async function collectChatGptFileArtifacts(params: {\n+  Network: ChromeClient[\"Network\"];\n+  sessionId?: string;\n+  answerMarkdown: string;\n+  logger?: BrowserLogger;\n+  fetchImpl?: typeof fetch;\n+}): Promise<{ artifacts: SessionArtifact[]; failures: number }> {\n+  const sources = params.sessionId ? extractChatGptSandboxFiles(params.answerMarkdown) : [];\n+  if (!sources.length) return { artifacts: [], failures: 0 };\n+  const cookies = await params.Network.getCookies({ urls: [\"https://chatgpt.com/\"] });\n+  const header = (cookies.cookies ?? [])\n+    .filter((cookie) => cookie.name && typeof cookie.value === \"string\")\n+    .map((cookie) => `${cookie.name}=${cookie.value}`)\n+    .join(\"; \");\n+  if (!header) {\n+    params.logger?.(\"[browser] Cannot save ChatGPT files: missing session cookies\");\n+    return { artifacts: [], failures: sources.length };\n+  }\n+  const dir = resolveSessionArtifactsDir(params.sessionId!);\n+  await fs.mkdir(dir, { recursive: true });\n+  const artifacts: SessionArtifact[] = [];\n+  let failures = 0;\n+  for (const source of sources) {\n+    const relative = source.slice(SANDBOX_PREFIX.length);\n+    const url = DOWNLOAD_BASE + relative.split(\"/\").map(encodeURIComponent).join(\"/\");\n+    let target: string | undefined;\n+    let file: Awaited<ReturnType<typeof fs.open>> | undefined;\n+    try {\n+      const response = await (params.fetchImpl ?? fetch)(url, {\n+        headers: { cookie: header },\n+        redirect: \"error\",\n+        signal: AbortSignal.timeout(DOWNLOAD_TIMEOUT_MS),\n+      });\n+      if (!response.ok || !response.body) throw new Error(`HTTP ${response.status}`);\n+      const filename = path.basename(relative).replace(/[^a-zA-Z0-9._-]/g, \"_\").slice(0, 120);\n+      const reserved = await reserveFile(dir, filename || \"download\");\n+      file = reserved.file;\n+      target = reserved.target;\n+      let size = 0;\n+      for await (const chunk of response.body) {\n+        size += chunk.byteLength;\n+        if (size > MAX_BYTES) throw new Error(\"Download size limit exceeded\");\n+        await file.writeFile(chunk);\n+      }\n+      await file.close();\n+      file = undefined;\n+      artifacts.push({ kind: \"file\", path: target, label: path.basename(target),\n+        mimeType: response.headers.get(\"content-type\") ?? undefined,\n+        sizeBytes: size, sourceUrl: source });\n+      params.logger?.(`[browser] Saved ChatGPT file artifact to ${target}`);\n+    } catch (error) {\n+      failures += 1;\n+      params.logger?.(`[browser] Could not save ChatGPT file artifact: ${String(error)}`);\n+      await file?.close().catch(() => {});\n+      if (target) await fs.unlink(target).catch(() => {});\n+    }\n+  }\n+  return { artifacts, failures };\n+}\ndiff --git a/src/browser/index.ts b/src/browser/index.ts\nindex b8eac98..e774df4 100644\n--- a/src/browser/index.ts\n+++ b/src/browser/index.ts\n@@ -80,6 +80,7 @@ import {\n   saveDeepResearchReportArtifact,\n } from \"./artifacts.js\";\n import { collectGeneratedImageArtifacts } from \"./chatgptImages.js\";\n+import { collectChatGptFileArtifacts } from \"./ch"
